     shop_id
    ,type as shop_scs_type
from regds_listing.dim_scs_shop_list_df
where grass_region in (${grass_region}) and type in ('scs-local','scs-cb')
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW cspu_label_${grass_region_without_quote} AS
select
     cspu_id
    ,order_cnt as cspu_l1d_order_cnt
from srdi_mart.dws_sr_data_warehouse_tc_pb_cspu_level_1d
WHERE grass_region IN (${grass_region})
and local_date = data_infra.max_pt('srdi_mart.dws_sr_data_warehouse_tc_pb_cspu_level_1d', 'local_date', "grass_region=${grass_region} and local_date<${regional_date}")
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW ecpm_label_${grass_region_without_quote} AS
SELECT item_id
,ecpm_tag as ecpm_l1d_tag
from srdi_mart.dws_sr_data_warehouse_tc_pb_item_level_ecpm_1d
where grass_region IN (${grass_region})
and regional_date = data_infra.max_pt('srdi_mart.dws_sr_data_warehouse_tc_pb_item_level_ecpm_1d', 'regional_date', "grass_region=${grass_region} and regional_date<${regional_date}")
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW ads_active_item_${grass_region_without_quote} AS
select
     item_id
    ,max(ads_id) as ads_id
from mp_paidads.dim_active_item__reg_s0_live
WHERE grass_region IN (${grass_region})
and placement in (40,50) -- limit roi2 ads itemid
group by
     item_id
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW buybox_cspu_tag_${grass_region_without_quote} AS
select
     cspu_id
    ,max(cspu_buybox_boost_weeks) as cspu_buybox_boost_weeks --现有逻辑下，一个cspuid是可以属于多个vitemid的，我们取最大cspu_buybox_boost_weeks
from(
    select
         cspu_id
        ,vitem_id
    from srdi_mart.dws_sr_data_warehouse_vsku_vitem_cspu_1d
    WHERE grass_region IN (${grass_region})
    and local_date = data_infra.max_pt('srdi_mart.dws_sr_data_warehouse_vsku_vitem_cspu_1d', 'local_date', "grass_region=${grass_region} and local_date<${regional_date}")
    group by --这里进行聚合，防止后续dws扩充维度
         cspu_id
        ,vitem_id
) a
left join (
    select
         vitem_id
        ,CEIL((DATEDIFF(date_timezone_convert(${regional_date},${regional_hour},'SG',${grass_region},"yyyy-MM-dd"),publish_local_date)+1)/7) as cspu_buybox_boost_weeks
    from srdi_mart.dim_sr_data_warehouse_vsku_vitem
    WHERE grass_region IN (${grass_region})
    and local_date = data_infra.max_pt('srdi_mart.dim_sr_data_warehouse_vsku_vitem', 'local_date', "grass_region=${grass_region} and local_date<${regional_date}")
) b on a.vitem_id=b.vitem_id
group by cspu_id
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW cheapest_raw_${grass_region_without_quote} AS
select
     cspu_id
    ,model_id
    ,item_id
    ,shop_id
    ,business_type
from paimon.rcmd_feature.ods_sr_data_warehouse_pb_one_variation
where grass_region in (${grass_region}) and model_id>0 -- =0 is deleted cheapest,which its cspu doesn't have cheapest model currently
and cspu_tag <> 8
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW cheapest_model_${grass_region_without_quote} AS
select
     a.cspu_id
    ,model_id
    ,item_id
    ,shop_id
    ,business_type
    ,if(business_type in (3,4), 1, 0)   as is_winner
    ,if(business_type in (1,2) and (b.cspu_l1d_order_cnt is null or b.cspu_l1d_order_cnt > 0), 1,0)   as is_buyer_cheapest
    ,b.cspu_l1d_order_cnt
from cheapest_raw_${grass_region_without_quote} a
left join cspu_label_${grass_region_without_quote} b on a.cspu_id=b.cspu_id
;
--sql_divide_splitter--

cache table cheapest_tag_${grass_region_without_quote} AS
select
     d.cspu_id
    ,d.model_id
    ,d.item_id
    ,d.shop_id
    ,business_type
    ,is_winner
    ,is_buyer_cheapest
    ,cspu_l1d_order_cnt
    ,if(shop_scs_type is null,'non-scs',shop_scs_type) as shop_scs_type
    ,coalesce(f.cspu_buybox_boost_weeks,9999) as cspu_buybox_boost_weeks
    ,g.ads_id
    ,case
        when if(${grass_region}='TW',is_buyer_cheapest=1,is_winner=1) and shop_scs_type in ('scs-local','scs-cb') then 2 -- scs winner
        when is_winner=1 then 3         -- normal winner
        when is_buyer_cheapest=1 then 5 -- cheapest   这里也会有scs ，因为winner cmt 覆盖不到所有的scs cspuid，不过这里会当成普通cheapest对待
     end as main_model_type
from cheapest_model_${grass_region_without_quote} d
left join shop_type_${grass_region_without_quote} e on d.shop_id=e.shop_id
left join buybox_cspu_tag_${grass_region_without_quote} f on d.cspu_id=f.cspu_id
left join ads_active_item_${grass_region_without_quote} g on d.item_id=g.item_id
where d.is_winner=1 or d.is_buyer_cheapest=1 -- 清除掉cheapest 中不满足cspu_l1d_order_cnt条件的数据
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW vmodel_${grass_region_without_quote} AS
SELECT model_id
from paimon.srdi_mart.ods_sr_data_warehouse_vsku_model_mapping
where grass_region in (${grass_region})
and status=1
-- 剔除 live test 的vitem
and (case
       when ${grass_region}='PH' then vitem_id not in (28220985573,25089553214,24439553114)
       when ${grass_region}='TH' then vitem_id not in (25690469056,27623537795,29873533900)
       else true
end)
group by 1
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_tc_pb_one_variation_minf
PARTITION (grass_region = ${grass_region}, regional_date = ${regional_date}, regional_hour = ${regional_hour}, regional_minute=${regional_minute})
select /*+ REPARTITION(100) */
     cspu_id
    ,a.model_id
    ,a.item_id
    ,shop_id
    ,main_model_type
    ,main_item_type
    ,is_winner
    ,is_buyer_cheapest
    ,shop_scs_type
    ,cspu_l1d_order_cnt
    ,cspu_buybox_boost_weeks
    ,ads_id
    ,ecpm_l1d_tag
    ,if(d.model_id is not null, 1, 0) is_buybox
from cheapest_tag_${grass_region_without_quote} a
left join(
    select
        item_id
        ,min(main_model_type) as main_item_type
    from cheapest_tag_${grass_region_without_quote}
    group by item_id
) b on a.item_id =b.item_id
left join ecpm_label_${grass_region_without_quote} c
on a.item_id = c.item_id
left join vmodel_${grass_region_without_quote} d
on a.model_id = d.model_id

